#include "stdlib/stats/base/ndarray/snanmskrange.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include <stdint.h>

/**
* Computes the range of a single-precision floating-point strided array according to a mask, ignoring `NaN` values.
*
* @param N             number of indexed elements
* @param x             input array
* @param strideX       x stride length
* @param offsetX       starting index for x
* @param mask          mask array
* @param strideMask    mask stride length
* @param offsetMask    starting index for mask
* @return              range
*/
static float stdlib_strided_snanmskrange_ndarray( const int64_t N, const float *x, const int64_t strideX, const int64_t offsetX, const uint8_t *mask, const int64_t strideMask, const int64_t offsetMask ) {
	int64_t ix;
	int64_t im;
	int64_t i;
	float min;
	float max;
	float v;

	if ( N <= 0 ) {
		v = 0.0f;
		return v / v; // NaN
	}

	ix = offsetX;
	im = offsetMask;

	for ( i = 0; i < N; i++ ) {
		if ( mask[ im ] == 0 ) {
			v = x[ ix ];
			if ( !stdlib_base_is_nanf( v ) ) {
				min = v;
				max = v;
				break;
			}
		}
		ix += strideX;
		im += strideMask;
	}
	if ( i == N ) {
		v = 0.0f;
		return v / v; // NaN
	}

	i += 1;
	ix += strideX;
	im += strideMask;
	for ( ; i < N; i++ ) {
		if ( mask[ im ] == 0 ) {
			v = x[ ix ];
			if ( !stdlib_base_is_nanf( v ) ) {
				if ( v < min ) {
					min = v;
				} else if ( v > max ) {
					max = v;
				}
			}
		}
		ix += strideX;
		im += strideMask;
	}
	return max - min;
}

/**
* Compute the range of a one-dimensional single-precision floating-point ndarray according to a mask, ignoring `NaN` values.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional mask ndarray.
*
* @param arrays    list containing ndarrays
* @return          range
*/
float stdlib_stats_snanmskrange( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];

	const struct ndarray *mask = arrays[ 1 ];

	return stdlib_strided_snanmskrange_ndarray( stdlib_ndarray_dimension( x, 0 ), (const float *)stdlib_ndarray_data( x ), stdlib_ndarray_stride_elements( x, 0 ), stdlib_ndarray_offset_elements( x ), (const uint8_t *)stdlib_ndarray_data( mask ), stdlib_ndarray_stride_elements( mask, 0 ), stdlib_ndarray_offset_elements( mask ) );
}
